{
  "incident": {
    "component": "kubernetes",
    "category": "disk_pressure",
    "status": "firing",
    "summary": "PVC data-postgres-0 in namespace billing is filling up with an estimated 4 hours of capacity remaining."
  },
  "assessment": {
    "urgency": "high",
    "rationale": "Time-to-exhaustion (TTE) is estimated at 4.0 hours, which is below the 12h threshold for high urgency."
  },
  "facts": [
    "filesystem_size_bytes = 53687091200.0",
    "filesystem_available_bytes = 4294967296.0",
    "growth_rate_bytes_per_hour = 1073741824.0",
    "storage_class = gp3-csi",
    "allow_volume_expansion = True",
    "label.alertname = KubePersistentVolumeFillingUp",
    "label.namespace = billing",
    "label.persistentvolumeclaim = data-postgres-0",
    "Postgres runs as a StatefulSet with 1 replica."
  ],
  "missing_context": [
    {
      "item": "user_impact",
      "why": "To determine if this is a 'fire' requiring immediate mitigation or if we have time for proper investigation [global.impact.001].",
      "how_to_check": "Check error rate/latency SLO dashboards for the billing service and check internal support channels."
    },
    {
      "item": "recent_changes",
      "why": "To see if a recent deployment or config change triggered the increased growth rate [global.context.001].",
      "how_to_check": "Check CI/CD history, Helm releases, or ArgoCD/Flux history for the billing namespace."
    },
    {
      "item": "reclaim_policy",
      "why": "To understand the risk of PVC deletion [k8s.storage.003].",
      "how_to_check": "kubectl get pv <pv-name> -o jsonpath='{.spec.persistentVolumeReclaimPolicy}'"
    }
  ],
  "immediate_actions": [
    {
      "action": "Expand the PVC 'data-postgres-0'",
      "purpose": "Buy time by increasing available capacity [global.capacity.001].",
      "conditions": "StorageClass must allow expansion (confirmed: True) and CSI must support it.",
      "expected_effect": "Increased filesystem capacity.",
      "risks": "Online resize may add I/O load to an already struggling disk [global.harm.001]. Since it is a single-replica StatefulSet, if the driver requires a pod restart to complete the resize, it will cause downtime [k8s.storage.001].",
      "requires_approval": true,
      "verify": "kubectl describe pvc data-postgres-0 | grep -i 'FileSystemResizePending'",
      "rule_ids": [
        "k8s.storage.001",
        "global.capacity.001",
        "global.harm.001"
      ]
    }
  ],
  "investigation_steps": [
    {
      "step": "Identify top growing directories inside the pod",
      "hypothesis": "A specific log file, WAL segment, or data directory is consuming space rapidly [k8s.storage.004].",
      "how_to_check": "kubectl exec -it data-postgres-0 -n billing -- du -xh --max-depth=2 /var/lib/postgresql | sort -h | tail"
    },
    {
      "step": "Check Postgres-specific growth (WAL/Logs)",
      "hypothesis": "Postgres WAL archiving or heavy transaction volume is driving growth [k8s.storage.004].",
      "how_to_check": "Check Postgres configuration for max_wal_size and archiving settings; check for large files in the data directory."
    },
    {
      "step": "Analyze growth trends",
      "hypothesis": "The current growth is an anomaly compared to historical patterns [global.history.001].",
      "how_to_check": "PromQL: predict_linear(kubelet_volume_stats_available_bytes{persistentvolumeclaim='data-postgres-0'}[6h], 4*3600) and compare with 'offset 1w'."
    }
  ],
  "root_cause_hypotheses": [
    "Runaway database growth (e.g., large table inserts or index builds).",
    "Postgres WAL (Write Ahead Log) accumulation due to failed archiving or high transaction volume.",
    "Unexpectedly large log files within the volume."
  ],
  "dangerous_operations": [
    {
      "operation": "Deleting files inside /var/lib/postgresql",
      "why_dangerous": "Can cause database corruption [linux.storage.006].",
      "rule_id": "linux.storage.006"
    },
    {
      "operation": "Deleting the PVC to recreate it larger",
      "why_dangerous": "Will destroy all data if reclaimPolicy is 'Delete' [k8s.storage.003].",
      "rule_id": "k8s.storage.003"
    },
    {
      "operation": "Scaling StatefulSet to zero",
      "why_dangerous": "Causes immediate service downtime [k8s.storage.002].",
      "rule_id": "k8s.storage.002"
    }
  ],
  "applied_expert_rules": [
    "global.impact.001",
    "global.harm.001",
    "global.context.001",
    "global.history.001",
    "global.safety.001",
    "global.capacity.001",
    "global.triage.001",
    "global.evidence.001",
    "k8s.storage.001",
    "k8s.storage.002",
    "k8s.storage.003",
    "k8s.storage.004",
    "linux.storage.001",
    "linux.storage.006"
  ],
  "incident_update": "🚨 *High Urgency*: PVC `data-postgres-0` in `billing` is filling up (92% used). Estimated TTE is ~4 hours. We are investigating the cause (WAL/logs) and preparing to expand the PVC. *Next step*: Verify user impact and check for recent changes."
}
